<?php
require_once __DIR__ . '/../../includes/config.php';
require_once __DIR__ . '/../../includes/auth_check.php';
require_once __DIR__ . '/../../includes/functions.php';
if (($_SESSION['user_role'] ?? '') !== 'super_admin') { header('Location: ' . BASE_URL . '/index.php'); exit; }
$message = null; $error = null;
try {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $action = $_POST['action'] ?? '';
        if ($action === 'save_offense') {
            $params = [trim($_POST['offense_name'] ?? ''), $_POST['category'] ?? '', trim($_POST['description'] ?? ''), isset($_POST['is_active']) ? 1 : 0];
            if ($params[0] === '' || !in_array($params[1], ['Minor', 'Major'], true)) throw new RuntimeException('Enter a valid violation name and category.');
            if (!empty($_POST['offense_id'])) { $params[] = (int)$_POST['offense_id']; executeQuery('UPDATE offense_types SET offense_name = ?, category = ?, description = ?, is_active = ? WHERE offense_id = ?', $params); $message = 'Violation updated.'; }
            else { executeQuery('INSERT INTO offense_types (offense_name, category, description, is_active) VALUES (?, ?, ?, ?)', $params); $message = 'Violation added.'; }
        } elseif ($action === 'save_sanction') {
            $name = trim($_POST['sanction_name'] ?? ''); $level = max(1, min(5, (int)($_POST['severity_level'] ?? 1))); $description = trim($_POST['sanction_description'] ?? ''); $active = isset($_POST['sanction_active']) ? 1 : 0;
            if ($name === '') throw new RuntimeException('Enter a sanction name.');
            if (!empty($_POST['sanction_id'])) { executeQuery('UPDATE sanctions SET sanction_name = ?, severity_level = ?, description = ?, is_active = ? WHERE sanction_id = ?', [$name, $level, $description, $active, (int)$_POST['sanction_id']]); $message = 'Sanction updated.'; }
            else { executeQuery('INSERT INTO sanctions (sanction_name, severity_level, description, is_active) VALUES (?, ?, ?, ?)', [$name, $level, $description, $active]); $message = 'Sanction added.'; }
        } elseif ($action === 'save_escalation') { setSystemSetting('escalation_minor_count', max(1, (int)($_POST['escalation_minor_count'] ?? 3))); $message = 'Escalation rule saved.'; }
    }
} catch (Throwable $e) { $error = $e->getMessage(); }
$offenses = fetchAll('SELECT offense_id, offense_name, category, description, is_active FROM offense_types ORDER BY category, offense_name');
$sanctions = fetchAll('SELECT sanction_id, sanction_name, severity_level, description, is_active FROM sanctions ORDER BY severity_level, sanction_name');
$escalationCount = getSystemSetting('escalation_minor_count', '3'); $pageTitle = 'Case Rules'; $adminName = getFormattedUserName();
?>
