chars($item['description'] ?? '') ?></td><td class="px-6 py-4 text-sm"><span class="inline-flex rounded-full px-2 py-1 text-xs font-semibold <?= $item['is_active'] ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300' ?>"><?= $item['is_active'] ? 'Active' : 'Inactive' ?></span></td><td class="px-6 py-4"><button type="button" class="edit-offense px-3 py-2 border border-gray-300 dark:border-slate-600 rounded-lg text-sm hover:bg-gray-100 dark:hover:bg-slate-700" data-id="<?= (int)$item['offense_id'] ?>" data-name="<?= htmlspecialchars($item['offense_name'], ENT_QUOTES) ?>" data-category="<?= htmlspecialchars($item['category'], ENT_QUOTES) ?>" data-description="<?= htmlspecialchars($item['description'] ?? '', ENT_QUOTES) ?>" data-active="<?= (int)$item['is_active'] ?>">Edit</button></td></tr><?php endforeach; ?></tbody></table></div></section>
